CREATE TABLE IF NOT EXISTS event_write_set (
  event_name TEXT NOT NULL,
  version    INT  NOT NULL,
  table_name TEXT NOT NULL,
  ord        INT  NOT NULL DEFAULT 0,
  PRIMARY KEY (event_name, version, table_name)
);

CREATE TABLE IF NOT EXISTS event_test_data (
  id         TEXT PRIMARY KEY,
  event_name TEXT NOT NULL,
  version    INT  NOT NULL,
  table_name TEXT NOT NULL,
  ord        INT  NOT NULL DEFAULT 0,
  body       JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS event_test_data_ev_idx
  ON event_test_data (event_name, version, table_name, ord);

